{"filePath":"d:\WebDev\Hackathon\AIBuildFest\MatriSense\backend\src\triage\ruleRunner.js","content":"const { Engine } = require('json-rules-engine');
const rulesConfig = require('./rules.json');

const buildEngine = () => {
  const engine = new Engine();

  if (rulesConfig?.rules?.length) {
    rulesConfig.rules.forEach((rule) => engine.addRule(rule));
  }

  return engine;
};

const runRules = async (facts = {}) => {
  const engine = buildEngine();
  const { events, failureEvents } = await engine.run(facts);

  return {
    events,
    failureEvents,
  };
};

module.exports = {
  buildEngine,
  runRules,
};
"}

{"filePath":"d:\WebDev\Hackathon\AIBuildFest\MatriSense\backend\src\triage\decisionBuilder.js","content":"const { RISK_LEVELS, ACTIONS } = require('./constants');

const DEFAULT_DECISION = {
  riskLevel: RISK_LEVELS.UNKNOWN,
  recommendedAction: ACTIONS.CONTACT_HEALTH_WORKER,
  reasons: ['Insufficient data to determine risk level.'],
  matchedRules: [],
};

const buildDecision = (events = []) => {
  if (!events.length) {
    return { ...DEFAULT_DECISION };
  }

  const riskEvents = events
    .filter((event) => event.type === 'riskLevel')
    .map((event) => event.params)
    .filter(Boolean);

  if (!riskEvents.length) {
    return { ...DEFAULT_DECISION };
  }

  const highest = riskEvents.reduce((acc, current) => {
    const priority = {
      [RISK_LEVELS.HIGH]: 3,
      [RISK_LEVELS.MEDIUM]: 2,
      [RISK_LEVELS.LOW]: 1,
      [RISK_LEVELS.UNKNOWN]: 0,
    };

    return priority[current.level] > priority[acc.level] ? current : acc;
  }, riskEvents[0]);

  return {
    riskLevel: highest.level || RISK_LEVELS.UNKNOWN,
    recommendedAction: highest.action || ACTIONS.CONTACT_HEALTH_WORKER,
    reasons: riskEvents.map((event) => event.reason).filter(Boolean),
    matchedRules: riskEvents.map((event) => event.ruleName).filter(Boolean),
  };
};

module.exports = {
  buildDecision,
};
"}

