const { buildDecision } = require('./decisionBuilder');

const evaluateTriage = async (facts = {}) => {
  const { events } = await runRules(facts);
  const decision = buildDecision(events);

  return {
    decision,
    events,
  };
};

module.exports = {
  evaluateTriage,
};
"}

